def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False]*w for _ in range(h)]; ups = []; downs = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 2 and not seen[i][j]:
                stack = [(i, j)]; seen[i][j] = True; comp = []
                while stack:
                    y, x = stack.pop(); comp.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and not seen[ny][nx]:
                            seen[ny][nx] = True; stack.append((ny, nx))
                bar_row = max(y for y, x in comp) if any(grid[y-1][x] == 2 for y, x in comp) else min(y for y, x in comp)
                # orientation: stem above bar -> up
                rows = {}
                for y, x in comp: rows.setdefault(y, []).append(x)
                wide = max(rows, key=lambda r: len(rows[r]))
                jr = next(r for r in rows if len(rows[r]) == 1)
                jc = rows[jr][0]
                (ups if jr < wide else downs).append((jr, jc))
    ups.sort(); downs.sort()
    corners = [(0,0),(0,2),(2,0),(2,2)]
    out = [[0]*6 for _ in range(3)]
    for k, (r, c) in enumerate(ups[:4]):
        out[corners[k][0]][corners[k][1]] = 3
    for k, (r, c) in enumerate(downs[:4]):
        out[corners[k][0]][corners[k][1]+3] = 1
    return out

